      "required": false,
      "default": 85
    },
    "ctxWarnPercent": {
      "type": "number",
      "title": "Context amber from, percent",
      "description": "The context figure turns amber from this fill.",
      "required": false,
      "default": 50
    },
    "ctxRedPercent": {
      "type": "number",
      "title": "Context red from, percent",
      "description": "The context figure turns red from this fill.",
      "required": false,
      "default": 80
    }
  }
}

